/**
 * Solana DvP program helpers (solana-foundation/dvp v0.1.0; client generated into ../dvp/generated by `pnpm codama`).
 * Qupon never CPIs into that program — it only admits the trade's bond escrow (docs/03-domain.md §4a).
 */
import {
	type Address,
	address,
	getAddressEncoder,
	getBase64Encoder,
	getProgramDerivedAddress,
	getU64Encoder,
	type ReadonlyUint8Array,
} from "@solana/kit";
import { findAssociatedTokenPda } from "@solana-program/token-2022";
import { DVP_SWAP_PROGRAM_PROGRAM_ADDRESS, getSwapDvpDecoder, type SwapDvp } from "../dvp/generated/index.js";
import type { QuponRpc } from "./tx.js";

export const MEMO_PROGRAM_ADDRESS = address("MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr");
/** Fixed size of a `SwapDvp` account (no discriminator). */
export const SWAP_DVP_SIZE = 458;

const U64_MAX = (1n << 64n) - 1n;
const enc = new TextEncoder();
const key = (a: Address): ReadonlyUint8Array => getAddressEncoder().encode(a);

export interface TradeSeeds {
	readonly settlementAuthority: Address;
	/** Seller — delivers the bond leg (`mint_a`). */
	readonly userA: Address;
	/** Buyer — delivers the cash leg (`mint_b`). */
	readonly userB: Address;
	readonly mintA: Address;
	readonly mintB: Address;
	readonly nonce: bigint;
}

/** `SwapDvp` — seeds ["dvp", settlement_authority, user_a, user_b, mint_a, mint_b, nonce u64 LE]. */
export async function findSwapDvpPda(t: TradeSeeds): Promise<Address> {
	return (
		await getProgramDerivedAddress({
			programAddress: DVP_SWAP_PROGRAM_PROGRAM_ADDRESS,
			seeds: [enc.encode("dvp"), key(t.settlementAuthority), key(t.userA), key(t.userB), key(t.mintA), key(t.mintB), getU64Encoder().encode(t.nonce)],
		})
	)[0];
}

/** Nonce tombstone — seeds ["nonce", swap_dvp]; created with the trade and never closed. */
export async function findNonceTombstonePda(swapDvp: Address): Promise<Address> {
	return (await getProgramDerivedAddress({ programAddress: DVP_SWAP_PROGRAM_PROGRAM_ADDRESS, seeds: [enc.encode("nonce"), key(swapDvp)] }))[0];
}

/** A leg's escrow: the ATA of the `SwapDvp` PDA for that leg's mint. */
export async function escrowAta(swapDvp: Address, mint: Address, tokenProgram: Address): Promise<Address> {
	return (await findAssociatedTokenPda({ owner: swapDvp, mint, tokenProgram }))[0];
}

/** Decode a `SwapDvp` account; anything not owned by the DvP program or not exactly 458 bytes is refused. */
export function decodeTrade(owner: Address, data: ReadonlyUint8Array): SwapDvp {
	if (owner !== DVP_SWAP_PROGRAM_PROGRAM_ADDRESS) throw new Error(`not a Solana DvP trade: account owner is ${owner}`);
	if (data.length !== SWAP_DVP_SIZE) throw new Error(`not a Solana DvP trade: ${data.length} bytes, expected ${SWAP_DVP_SIZE}`);
	return getSwapDvpDecoder().decode(data);
}

/** The trade record at `swapDvp`, or `null` once the DvP program has closed it (settled, cancelled or rejected). */
export async function readTrade(rpc: QuponRpc, swapDvp: Address): Promise<SwapDvp | null> {
	const { value } = await rpc.getAccountInfo(swapDvp, { commitment: "confirmed", encoding: "base64" }).send();
	return value === null ? null : decodeTrade(value.owner, getBase64Encoder().encode(value.data[0]));
}

/** Token amount of an SPL / Token-2022 account (u64 LE at offset 64), or `null` if the account does not exist. */
export async function tokenAmount(rpc: QuponRpc, account: Address): Promise<bigint | null> {
	const { value } = await rpc.getAccountInfo(account, { commitment: "confirmed", encoding: "base64" }).send();
	if (value === null) return null;
	const data = getBase64Encoder().encode(value.data[0]);
	return new DataView(data.buffer, data.byteOffset, data.byteLength).getBigUint64(64, true);
}

/** `units × price` in minor units of the cash asset, refused beyond u64. */
export function cashAmount(units: bigint, price: bigint): bigint {
	if (units <= 0n) throw new Error("units: must be > 0");
	if (price <= 0n) throw new Error("price: must be > 0 minor units per bond");
	const total = units * price;
	if (total > U64_MAX) throw new Error(`cash amount ${total} does not fit in u64`);
	return total;
}

export type TradeStatus = "awaiting_funding" | "ready" | "closed";

/** `null` funding = that escrow no longer exists, i.e. the DvP program closed the trade. */
export function tradeStatus(units: bigint, cash: bigint, fundedUnits: bigint | null, fundedCash: bigint | null): TradeStatus {
	if (fundedUnits === null || fundedCash === null) return "closed";
	return fundedUnits >= units && fundedCash >= cash ? "ready" : "awaiting_funding";
}

export type TradeSide = "seller" | "buyer";

export function parseSide(s: string): TradeSide {
	if (s === "seller" || s === "buyer") return s;
	throw new Error(`--side: expected seller or buyer, got '${s}'`);
}

export interface FundingLeg {
	readonly mint: Address;
	readonly tokenProgram: Address;
	readonly amount: bigint;
}

/** The leg `signer` owes on `side`; refuses a signer who is not that side's party (verify before funding). */
export function fundingLeg(trade: SwapDvp, signer: Address, side: TradeSide): FundingLeg {
	const party = side === "seller" ? trade.userA : trade.userB;
	if (party !== signer) throw new Error(`${signer} is not the ${side} of this trade (${party} is)`);
	return side === "seller"
		? { mint: trade.mintA, tokenProgram: trade.tokenProgramA, amount: trade.amountA }
		: { mint: trade.mintB, tokenProgram: trade.tokenProgramB, amount: trade.amountB };
}
